-- One row per sales region. regionCode is the Ermine `region` value every view exposes.
CREATE TABLE dbo.dim_region (
  [regionId] int NOT NULL,
  [regionCode] nvarchar(40) NOT NULL,
  [regionName] nvarchar(80) NOT NULL,
  [regionGroup] nvarchar(8) NOT NULL,
  [countryName] nvarchar(80) NOT NULL,
  [countryCode] nvarchar(2) NOT NULL,
  [populationWeight] float NOT NULL,
  CONSTRAINT pk_dim_region PRIMARY KEY ([regionId]),
  CONSTRAINT uq_dim_region_regionCode UNIQUE ([regionCode])
);

-- The catalogue. productName is the Ermine `item` value (Sales.e).
CREATE TABLE dbo.dim_product (
  [productId] int NOT NULL,
  [sku] nvarchar(20) NOT NULL,
  [productName] nvarchar(80) NOT NULL,
  [category] nvarchar(40) NOT NULL,
  [subCategory] nvarchar(40) NOT NULL,
  [priceBand] nvarchar(10) NOT NULL,
  [listPrice] float NOT NULL,
  [unitCost] float NOT NULL,
  CONSTRAINT pk_dim_product PRIMARY KEY ([productId]),
  CONSTRAINT uq_dim_product_sku UNIQUE ([sku]),
  CONSTRAINT uq_dim_product_productName UNIQUE ([productName])
);

-- Sales channel (Ai/SalesByRegion.e channel dimension). isDirect is a Y/N String: the corpus has 0 Bool columns (SURVEY-CORPUS §5).
CREATE TABLE dbo.dim_channel (
  [channelId] int NOT NULL,
  [channelName] nvarchar(40) NOT NULL,
  [isDirect] nvarchar(1) NOT NULL,
  CONSTRAINT pk_dim_channel PRIMARY KEY ([channelId]),
  CONSTRAINT uq_dim_channel_channelName UNIQUE ([channelName])
);

-- Sales reps; each belongs to one region. repScore is the one Nullable Int (Present/SalesDashboard.e repScore).
CREATE TABLE dbo.dim_rep (
  [repId] int NOT NULL,
  [repName] nvarchar(80) NOT NULL,
  [regionId] int NOT NULL,
  [repTeam] nvarchar(40) NOT NULL,
  [hireDate] date NOT NULL,
  [repScore] int NULL,
  CONSTRAINT pk_dim_rep PRIMARY KEY ([repId]),
  CONSTRAINT fk_dim_rep_regionId FOREIGN KEY ([regionId]) REFERENCES dbo.dim_region ([regionId])
);

-- Customers; each belongs to one region (Algebra/OrderLedger.e customerDim, complete here: FKs are enforced).
CREATE TABLE dbo.dim_customer (
  [customerId] int NOT NULL,
  [customerName] nvarchar(120) NOT NULL,
  [customerTier] nvarchar(10) NOT NULL,
  [regionId] int NOT NULL,
  [signupDate] date NOT NULL,
  CONSTRAINT pk_dim_customer PRIMARY KEY ([customerId]),
