-- The calendar. xs = exactly the 8 sale days (so the `calendar` view equals FetchCrosstab.e's literal); s+ = every day of the tier range. monthName is FetchCrosstab's "YYYY-MM" key.
CREATE TABLE dbo.dim_date (
  [day] date NOT NULL,
  [yearNo] int NOT NULL,
  [quarterNo] int NOT NULL,
  [monthNo] int NOT NULL,
  [monthName] nvarchar(7) NOT NULL,
