  [weekdayNo] int NOT NULL,
  [weekdayName] nvarchar(9) NOT NULL,
  CONSTRAINT pk_dim_date PRIMARY KEY ([day])
);

-- One row per order line. lineAmount is the Ermine `amount`, quantity the Ermine `units`, both summed by the views.
CREATE TABLE dbo.fact_order_line (
  [orderId] int NOT NULL,
  [lineNo] int NOT NULL,
  [orderDate] date NOT NULL,
  [regionId] int NOT NULL,
  [customerId] int NOT NULL,
