  [quantity] int NOT NULL,
  [unitPrice] float NOT NULL,
  [discountPct] float NOT NULL,
  [lineAmount] float NOT NULL,
  [promoCode] nvarchar(20) NULL,
  CONSTRAINT pk_fact_order_line PRIMARY KEY ([orderId], [lineNo]),
  CONSTRAINT fk_fact_order_line_orderDate FOREIGN KEY ([orderDate]) REFERENCES dbo.dim_date ([day]),
  CONSTRAINT fk_fact_order_line_regionId FOREIGN KEY ([regionId]) REFERENCES dbo.dim_region ([regionId]),
  CONSTRAINT fk_fact_order_line_customerId FOREIGN KEY ([customerId]) REFERENCES dbo.dim_customer ([customerId]),
  CONSTRAINT fk_fact_order_line_productId FOREIGN KEY ([productId]) REFERENCES dbo.dim_product ([productId]),
  CONSTRAINT fk_fact_order_line_repId FOREIGN KEY ([repId]) REFERENCES dbo.dim_rep ([repId]),
  CONSTRAINT fk_fact_order_line_channelId FOREIGN KEY ([channelId]) REFERENCES dbo.dim_channel ([channelId])
);

-- A sales target per region per quarter; the `targets` view sums them per region.
