-- backs FetchData.e:20 `sales : [region, day, amount, units]`; key (region, day)
CREATE VIEW dbo.sales AS
SELECT r.regionCode AS region, f.orderDate AS day,
       SUM(f.lineAmount) AS amount, SUM(f.quantity) AS units
FROM dbo.fact_order_line AS f
JOIN dbo.dim_region AS r ON r.regionId = f.regionId
GROUP BY r.regionCode, f.orderDate;
GO

-- backs Sales.e:71-75 the Sale record (region, day, amount, units, item); key (region, day, item)
CREATE VIEW dbo.sales_items AS
SELECT r.regionCode AS region, f.orderDate AS day, p.productName AS item,
       SUM(f.lineAmount) AS amount, SUM(f.quantity) AS units
FROM dbo.fact_order_line AS f
JOIN dbo.dim_region AS r ON r.regionId = f.regionId
JOIN dbo.dim_product AS p ON p.productId = f.productId
GROUP BY r.regionCode, f.orderDate, p.productName;
GO

-- backs FetchData.e:33 `targets : [region, target]`; key (region)
CREATE VIEW dbo.targets AS
SELECT r.regionCode AS region, SUM(t.targetAmount) AS target
FROM dbo.fact_target AS t
JOIN dbo.dim_region AS r ON r.regionId = t.regionId
GROUP BY r.regionCode;
GO

-- backs FetchCrosstab.e `calendar : [day, monthName]` (a module-local literal today); key (day)
CREATE VIEW dbo.calendar AS
SELECT d.day AS day, d.monthName AS monthName
FROM dbo.dim_date AS d;
GO
